/* PENDING (not wired in, never run): failing-first regression checks for the single-scroll and single-focus-ring user bugs. Paste before 'if (TCTX) await TCTX.close();' in grader/design-grade.js, then take a RED run, then fix style.css (.mdd max-height/overflow; input:focus-visible inside .iw). */

  await kcheck('K50', 'One scroll only: at desktop 1280 and 1600, iPad landscape 1180 and iPad portrait 820, on every page (asset beside the list, Real, Saved, Finances, Assumptions, Buy order, Add, Import, Health, shortfall) no element other than the page itself scrolls (no overflow auto/scroll with content taller than the box and no fixed-height pane), except the listed exemptions (a phone info sheet, textareas and selects)', 10, 'sweep every page; list elements with overflow-y auto/scroll/overlay whose scrollHeight exceeds clientHeight', async () => {
    const P = new Parts(), bad = [], HS = ['#house-maple', '#house-g'];
    for (const [w, h, touch] of [[1280, 900, false], [1600, 900, false], [1180, 820, true], [820, 1180, true]]) { const C = await mkCtx({ autoExpand: false, isMobile: touch, hasTouch: touch, viewport: { width: w, height: h } }), pg = await mkPage(C, 'design-scroll');
      for (const p of ALLP.concat([['asset-md', seedS, '#house-maple', openAllOn]])) { try { await goAll(pg, p); const r = await pg.evaluate(() => { const out = []; document.querySelectorAll('body *').forEach((e) => { if (/^(TEXTAREA|SELECT|INPUT|HTML|BODY)$/.test(e.tagName) || e.closest('svg')) return; const s = getComputedStyle(e); if (/(auto|scroll|overlay)/.test(s.overflowY) && e.scrollHeight > e.clientHeight + 1 && e.clientHeight > 0) out.push((e.className || e.tagName) + ' ' + e.scrollHeight + '>' + e.clientHeight + ' mh=' + s.maxHeight); }); return out.slice(0, 3); }); if (r.length) bad.push(p[0] + '@' + w + ': ' + r.join(', ')); } catch (e) { bad.push(p[0] + '@' + w + ' crash'); } }
      await C.close(); }
    void HS; P.t(!bad.length, 'no inner scroll container on any page at 1280 / 1600 / 1180 / 820', 10, bad.slice(0, 4).join(' | ')); return P; });

  await kcheck('K51', 'One focus ring: a focused box, percent box, text box, select and text area shows a single rounded ring: the wrapper (.iw) carries it and the inner input has no outline or shadow; standalone fields have one outline with a rounded corner; screenshots grader/screens/v7-focus-<kind>.png', 8, 'keyboard-focus each field kind on desktop 1280, read computed outline / box-shadow / radius of the input and its wrapper', async () => {
    const P = new Parts(), C = await mkCtx({ autoExpand: false, isMobile: false, hasTouch: false, viewport: { width: 1280, height: 900 } }), pg = await mkPage(C, 'design-focus'), bad = [], seen = [];
    const KINDS = [['money', seedS, '#house-maple', '.iw input[data-num]'], ['percent', seedS, '#house-maple', '.iw:has(em) input[data-num]'], ['text', seedS, '#add', 'input[type=text]:not([data-num])'], ['select', seedS, '#house-maple', 'select'], ['textarea', seedS, '#assumptions', 'textarea']];
    for (const sc of ['light', 'dark']) { await pg.emulateMedia({ colorScheme: sc });
      for (const [kind, S0, hs, sel] of KINDS) { try { await loadOn(pg, S0(), hs); await openAllOn(pg); await pg.keyboard.press('Shift'); const el = pg.locator(sel).first(); if (!(await el.count())) { if (sc === 'light') bad.push(kind + ': not found'); continue; } await el.scrollIntoViewIfNeeded(); await el.focus(); await pg.waitForTimeout(60);
          const r = await el.evaluate((e) => { const cs = getComputedStyle(e), w = e.closest('.iw'), ws = w && getComputedStyle(w); const ow = parseFloat(cs.outlineWidth) * (cs.outlineStyle === 'none' ? 0 : 1); return { inner: { outline: ow, shadow: cs.boxShadow !== 'none', border: parseFloat(cs.borderTopWidth) > 0 && cs.borderTopStyle !== 'none' && !/^(INPUT)$/.test(e.tagName) }, wrap: w ? { shadow: ws.boxShadow !== 'none', radius: parseFloat(ws.borderTopLeftRadius) } : null, radius: parseFloat(cs.borderTopLeftRadius), tag: e.tagName }; });
          seen.push(kind);
          if (r.wrap) { if (!(r.wrap.shadow && r.wrap.radius >= 12 && r.inner.outline === 0 && !r.inner.shadow)) bad.push(kind + ' ' + sc[0] + ': ' + JSON.stringify(r)); } else { const rings = (r.inner.outline > 0 ? 1 : 0) + (r.inner.shadow ? 1 : 0); if (!(rings === 1 && r.radius >= 12)) bad.push(kind + ' ' + sc[0] + ': ' + JSON.stringify(r)); }
          if (sc === 'light') { const b = await (r.wrap ? el.locator('xpath=ancestor::*[contains(@class,"iw")][1]') : el).boundingBox(); if (b) await pg.screenshot({ path: path.join(SHOTS, 'v7-focus-' + kind + '.png'), clip: { x: Math.max(0, b.x - 12), y: Math.max(0, b.y - 12), width: Math.min(400, b.width + 24), height: b.height + 24 } }); } } catch (e) { bad.push(kind + ' crash ' + String(e.message).slice(0, 60)); } } }
    await C.close(); P.t(!bad.length, 'each field kind shows exactly one rounded focus ring, light and dark (' + [...new Set(seen)].join(',') + ')', 6, bad.slice(0, 3).join(' | ')); P.t(new Set(seen).size >= 5, 'all five field kinds were found and focused', 2, [...new Set(seen)].join(',')); return P; });
